void Main() {
    var count = 0;
    for (var outer = 0; outer < 3; outer = outer + 1) {
        for (var inner = 0; inner < 4; inner = inner + 1) {
            if (inner == 1) continue;
            if (inner == 3) break;
            count = count + 1;
        }
        if (outer == 1) continue;
        Print(outer);
    }
    Print(count);
    var i = 0;
    while (i < 5) {
        i = i + 1;
        if (i == 2) continue;
        if (i == 4) break;
        Print(i);
    }
    Print(i);
}
